"use client";

import React, { useEffect, useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import { ShieldAlert, ArrowLeft, Key, List, Trash2, Plus, Loader2 } from "lucide-react";
import Link from "next/link";
import { fetchWithAuth } from "@/lib/fetchWithAuth";
import { API_HOST } from "@/lib/api";

const API = API_HOST;

function getAuthHeaders() {
  try {
    const user = JSON.parse(localStorage.getItem("user") || "{}");
    return {
      "x-user-id": user.id || "",
    };
  } catch {
    return { "x-user-id": "" };
  }
}

export default function BetaAdminPanel() {
  const [codes, setCodes] = useState<any[]>([]);
  const [redemptions, setRedemptions] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [isAdmin, setIsAdmin] = useState<boolean | null>(null);
  const router = useRouter();

  // Form State
  const [newCode, setNewCode] = useState("");
  const [description, setDescription] = useState("");
  const [maxRedemptions, setMaxRedemptions] = useState("10");
  const [expiresInDays, setExpiresInDays] = useState("30");
  const [unlimitedSearch, setUnlimitedSearch] = useState(true);
  const [unlimitedPnr, setUnlimitedPnr] = useState(true);
  const [unlimitedLiveTracking, setUnlimitedLiveTracking] = useState(true);
  const [unlimitedSplitSearch, setUnlimitedSplitSearch] = useState(true);
  const [creating, setCreating] = useState(false);

  const verifyAdminAuth = useCallback(async () => {
    try {
      const userStr = localStorage.getItem("user");
      if (!userStr) {
        setIsAdmin(false);
        return;
      }
      const user = JSON.parse(userStr);
      if (!user.isAdmin) {
        setIsAdmin(false);
        return;
      }
      setIsAdmin(true);
      fetchData();
    } catch {
      setIsAdmin(false);
    }
  }, []);

  const fetchData = async () => {
    try {
      setLoading(true);
      const [codesRes, redemptionsRes] = await Promise.all([
        fetchWithAuth(`${API}/api/admin/beta/codes`, { headers: getAuthHeaders() }),
        fetchWithAuth(`${API}/api/admin/beta/redemptions`, { headers: getAuthHeaders() })
      ]);
      const codesJson = codesRes ? await codesRes.json() : { success: false };
      const redemptionsJson = redemptionsRes ? await redemptionsRes.json() : { success: false };
      if (codesJson.success) setCodes(codesJson.data);
      if (redemptionsJson.success) setRedemptions(redemptionsJson.data);
    } catch (err) {
      console.error("Failed to fetch beta data", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    verifyAdminAuth();
  }, [verifyAdminAuth]);

  const handleCreateCode = async (e: React.FormEvent) => {
    e.preventDefault();
    setCreating(true);
    try {
      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + parseInt(expiresInDays));

      const res = await fetchWithAuth(`${API}/api/admin/beta/codes`, {
        method: "POST",
        headers: { "Content-Type": "application/json", ...getAuthHeaders() },
        body: JSON.stringify({
          code: newCode,
          description,
          maxRedemptions: parseInt(maxRedemptions),
          expiresAt: expiresAt.toISOString(),
          unlimitedSearch,
          unlimitedPnr,
          unlimitedLiveTracking,
          unlimitedSplitSearch
        })
      });
      const json = await res.json();
      if (json.success) {
        setNewCode("");
        setDescription("");
        fetchData();
      } else {
        alert(json.error || "Failed to create code");
      }
    } catch (err) {
      console.error(err);
      alert("Error creating code");
    } finally {
      setCreating(false);
    }
  };

  const handleDisableCode = async (codeStr: string) => {
    if (!confirm(`Are you sure you want to disable ${codeStr}?`)) return;
    try {
      const res = await fetchWithAuth(`${API}/api/admin/beta/codes/${codeStr}/disable`, {
        method: "POST",
        headers: getAuthHeaders()
      });
      const json = await res.json();
      if (json.success) {
        fetchData();
      } else {
        alert(json.error || "Failed to disable code");
      }
    } catch (err) {
      console.error(err);
    }
  };

  if (isAdmin === false) {
    return <div className="p-8 text-center text-red-500">Access Denied</div>;
  }

  return (
    <div className="min-h-screen bg-app text-main font-sans p-4 md:p-8">
      <div className="max-w-6xl mx-auto">
        <div className="flex items-center gap-4 mb-8">
          <Link href="/admin" className="p-2 bg-input hover:bg-card border border-subtle rounded-xl transition">
            <ArrowLeft size={20} />
          </Link>
          <div>
            <h1 className="text-2xl font-bold flex items-center gap-2">
              <Key className="text-indigo-500" /> Beta Access Management
            </h1>
            <p className="text-muted text-sm">Manage beta codes and view tester redemptions</p>
          </div>
        </div>

        {loading ? (
          <div className="flex justify-center p-12">
            <Loader2 size={32} className="animate-spin text-indigo-500" />
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            {/* Create Code Form */}
            <div className="lg:col-span-1">
              <div className="bg-card border border-subtle rounded-xl p-6 shadow-sm sticky top-6">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <Plus size={18} className="text-indigo-400" /> Create Beta Code
                </h2>
                <form onSubmit={handleCreateCode} className="space-y-4">
                  <div>
                    <label className="text-xs text-muted mb-1 block">Code</label>
                    <input required value={newCode} onChange={(e) => setNewCode(e.target.value)} type="text" className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm focus:border-indigo-500 outline-none" placeholder="e.g. SUMMER25" />
                  </div>
                  <div>
                    <label className="text-xs text-muted mb-1 block">Description</label>
                    <input required value={description} onChange={(e) => setDescription(e.target.value)} type="text" className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm focus:border-indigo-500 outline-none" placeholder="e.g. Influencer Campaign" />
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="text-xs text-muted mb-1 block">Max Uses</label>
                      <input required value={maxRedemptions} onChange={(e) => setMaxRedemptions(e.target.value)} type="number" min="1" className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm focus:border-indigo-500 outline-none" />
                    </div>
                    <div>
                      <label className="text-xs text-muted mb-1 block">Valid Days</label>
                      <input required value={expiresInDays} onChange={(e) => setExpiresInDays(e.target.value)} type="number" min="1" className="w-full bg-input border border-subtle rounded-lg px-3 py-2 text-sm focus:border-indigo-500 outline-none" />
                    </div>
                  </div>
                  
                  <div className="pt-2 border-t border-subtle">
                    <label className="text-xs text-muted mb-2 block font-semibold">Bypass Quotas</label>
                    <div className="space-y-2">
                      <label className="flex items-center gap-2 text-sm">
                        <input type="checkbox" checked={unlimitedSearch} onChange={(e) => setUnlimitedSearch(e.target.checked)} className="rounded border-subtle bg-input" />
                        Unlimited Search
                      </label>
                      <label className="flex items-center gap-2 text-sm">
                        <input type="checkbox" checked={unlimitedPnr} onChange={(e) => setUnlimitedPnr(e.target.checked)} className="rounded border-subtle bg-input" />
                        Unlimited PNR
                      </label>
                      <label className="flex items-center gap-2 text-sm">
                        <input type="checkbox" checked={unlimitedLiveTracking} onChange={(e) => setUnlimitedLiveTracking(e.target.checked)} className="rounded border-subtle bg-input" />
                        Unlimited Live Tracking
                      </label>
                      <label className="flex items-center gap-2 text-sm">
                        <input type="checkbox" checked={unlimitedSplitSearch} onChange={(e) => setUnlimitedSplitSearch(e.target.checked)} className="rounded border-subtle bg-input" />
                        Unlimited Split Routing
                      </label>
                    </div>
                  </div>

                  <button disabled={creating} type="submit" className="w-full bg-indigo-600 hover:bg-indigo-700 text-white rounded-lg py-2 text-sm font-semibold transition mt-4 flex justify-center items-center gap-2">
                    {creating && <Loader2 size={16} className="animate-spin" />}
                    Generate Code
                  </button>
                </form>
              </div>
            </div>

            {/* Lists */}
            <div className="lg:col-span-2 space-y-6">
              <div className="bg-card border border-subtle rounded-xl p-6 shadow-sm">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <Key size={18} className="text-emerald-400" /> Active Beta Codes
                </h2>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead>
                      <tr className="text-muted border-b border-subtle">
                        <th className="pb-2">Code</th>
                        <th className="pb-2">Description</th>
                        <th className="pb-2">Uses</th>
                        <th className="pb-2">Status</th>
                        <th className="pb-2">Action</th>
                      </tr>
                    </thead>
                    <tbody>
                      {codes.length === 0 ? (
                        <tr><td colSpan={5} className="py-4 text-center text-muted">No codes found</td></tr>
                      ) : codes.map(c => (
                        <tr key={c.code} className="border-b border-subtle last:border-0">
                          <td className="py-3 font-mono text-emerald-400">{c.code}</td>
                          <td className="py-3 text-muted">{c.description}</td>
                          <td className="py-3">{c.currentRedemptions} / {c.maxRedemptions}</td>
                          <td className="py-3">
                            {c.isActive ? (
                              <span className="px-2 py-1 bg-emerald-500/10 text-emerald-400 rounded-full text-[10px] font-bold uppercase">Active</span>
                            ) : (
                              <span className="px-2 py-1 bg-red-500/10 text-red-400 rounded-full text-[10px] font-bold uppercase">Disabled</span>
                            )}
                          </td>
                          <td className="py-3">
                            {c.isActive && (
                              <button onClick={() => handleDisableCode(c.code)} className="p-1.5 bg-red-500/10 hover:bg-red-500/20 text-red-400 rounded-lg transition">
                                <Trash2 size={14} />
                              </button>
                            )}
                          </td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>

              <div className="bg-card border border-subtle rounded-xl p-6 shadow-sm">
                <h2 className="text-lg font-bold mb-4 flex items-center gap-2">
                  <List size={18} className="text-blue-400" /> Recent Redemptions
                </h2>
                <div className="overflow-x-auto">
                  <table className="w-full text-left text-sm">
                    <thead>
                      <tr className="text-muted border-b border-subtle">
                        <th className="pb-2">User ID</th>
                        <th className="pb-2">Code</th>
                        <th className="pb-2">Redeemed At</th>
                      </tr>
                    </thead>
                    <tbody>
                      {redemptions.length === 0 ? (
                        <tr><td colSpan={3} className="py-4 text-center text-muted">No redemptions yet</td></tr>
                      ) : redemptions.map(r => (
                        <tr key={r.id} className="border-b border-subtle last:border-0">
                          <td className="py-3 font-mono text-xs text-muted">{r.userId}</td>
                          <td className="py-3 font-mono text-emerald-400">{r.betaCode}</td>
                          <td className="py-3 text-muted">{new Date(r.redeemedAt).toLocaleString()}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
